L["CFG_STICKY_ENABLE_TIP"] = "开启：启用屏幕便签，包括编辑器栏中的便签按钮、笔记列表菜单中的“作为便签打开”、双击操作选项、神谕的便签前缀和 Shift+点击，以及显示／隐藏便签的按钮和快捷键。\n\n关闭：关闭所有便签并隐藏上述功能。原本会以便签形式打开的笔记（情境、闹钟）将改用弹出提示显示，快速笔记快捷键则会打开主窗口。重新开启后，先前打开的便签会恢复。"
