L["CFG_PNA_TIP"] = "开启：玩家笔记会自动保持最新：选中玩家时更新等级、公会和头衔；观察装备时更新装等和装备；并记录相遇次数。只有“备注”标题上方的部分会改变；您在“备注”下写的内容绝不会被修改。若手动修改笔记顶部内容，自动更新会停止，直到您在观察窗口中使用“更新装备和笔记”。\n\n关闭：玩家笔记只会在您手动更新时改变。"
