L["CFG_PNA_ON_TARGET_TIP"] = "开启：选中有笔记的玩家会计为一次相遇。\n\n关闭：选中他们仍会更新等级和公会，但不计为相遇。"
L["CFG_PNA_ON_INSPECT"] = "观察他们的装备"
L["CFG_PNA_ON_INSPECT_TIP"] = "开启：观察有笔记的玩家会计为一次相遇。\n\n关闭：观察他们仍会更新装备，但不计为相遇。"
L["CFG_PNA_ON_GROUP"] = "与他们组队"
L["CFG_PNA_ON_GROUP_TIP"] = "开启：有笔记的玩家加入您的队伍或团队时，计为一次相遇，并更新其等级。\n\n关闭：组队不会改变其笔记。"
L["CFG_PNA_ON_MOUSEOVER"] = "将鼠标指向他们"
L["CFG_PNA_ON_MOUSEOVER_TIP"] = "开启：将鼠标指向有笔记的玩家会计为一次相遇，并更新其等级和公会。只是路过的玩家也会计入。\n\n关闭：鼠标指向他们不会改变其笔记。"
L["CFG_HDR_UNDO_KEEP"] = "跨游戏会话保留"
L["CFG_UNDO_KEEP_DESC"] = "通常，“撤销”只会记住您本次登录后输入的内容：重新载入或登出后，笔记没有可撤销的步骤。开启此选项后，登出或重新载入时会保存每篇已编辑笔记的撤销和重做步骤，因此仍可撤销之前游戏会话中的更改。\n\n这些步骤存储在随 BigNoteBox 附带的 BigNoteBox History 插件中，使笔记和设置文件保持精简。若笔记超过下方设定的天数未编辑，已保存的步骤会被删除。如果笔记在“撤销”无法记录的地方发生更改（例如另一台电脑或通过导入），保存的步骤将被丢弃，以免应用到错误的文本。"
L["CFG_UNDO_KEEP_LABEL"] = "跨游戏会话保留撤销历史"
L["CFG_UNDO_KEEP_TIP"] = "开启：登出或重新载入时，每篇已编辑笔记的撤销和重做步骤都会保存在独立的 BigNoteBox History 插件中，下次打开笔记时仍可使用。如果笔记此后在其他地方发生更改（另一台电脑或通过导入），则会以空白历史开始。\n\n关闭：撤销和重做记录仅在本次游戏会话中有效。已保存的记录会一直保留，直到您将其重置。"
L["CFG_UNDO_KEEP_DAYS"] = "保留天数"
L["CFG_UNDO_KEEP_DAYS_TIP"] = "笔记超过指定天数未编辑时，将删除其已保存的历史记录。"
L["CFG_UNDO_KEEP_SIZE_FMT"] = "已保存的撤销历史：%s，涉及 %d 篇笔记"
L["CFG_UNDO_KEEP_SIZE_NONE"] = "已保存的撤销历史：无"
L["CFG_UNDO_KEEP_SIZE_MISSING"] = "插件列表中缺少 BigNoteBox History，或该插件已禁用，因此撤销记录只在本次游戏会话中保留。"
