L["CFG_CHK_REFBOX_AUTOADD_TIP"] = "拖入笔记正文或按住 Shift 点击插入的物品、法术、任务或宠物链接，也会添加到该笔记的参考框。\n从正文删除链接，不会将其从参考框移除。"
L["HISTORY_ADDON_NOTICE"] = "BigNoteBox History 缺失或已禁用。\n\nBigNoteBox 使用这个随附的小型插件保存笔记的旧版本（笔记历史），以及您选择保留的撤销步骤。它随 BigNoteBox 一同提供，通常应保持启用。\n\n在插件列表中启用它之前，“笔记历史”和“跨游戏会话保留撤销历史”功能均不可用。您的笔记不会受到影响。"
L["HISTORY_ADDON_NOTICE_NEVER"] = "不再显示"
