L["RESCUE_HDR"] = "找回笔记"
L["RESCUE_DESC"] = "如果笔记并未在 BigNoteBox 中删除，却意外消失（例如笔记文件损坏或被替换），它们的历史仍保存在 BigNoteBox History 插件中，可以在这里找回。找回的笔记会恢复最新正文，以及上次登出或重新载入时的其他内容：外观、标签、任务、参考框、情境、闹钟和归属（原角色；若该角色已不在列表中，则归入“全部”）。笔记丢失期间到期的闹钟不会响起，但会列在闹钟窗口中。如果笔记在开始保存这些内容之前就已丢失，则只会恢复正文、富文本模式、标签和任务，并归入“全部”。每篇找回的笔记都会保留全部历史版本（可从历史中恢复旧版本），并获得“已找回”标签，方便查找和检查。\n\n仍然存在但标题和正文都为空的笔记也会列出：“找回”会恢复其最新正文，空白状态则保留为一个历史版本。"
L["RESCUE_ALL_BTN"] = "全部找回"
